## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int BIT_CLOCKS = 40;  // prescale 5 * 8 clocks per bit

  logic clk = 1'b0;
  logic rst = 1'b1;
  logic rxd = 1'b1;
  logic m_axis_tready = 1'b0;
  logic [15:0] prescale = 16'd5;

  wire [7:0] m_axis_tdata;
  wire m_axis_tvalid;
  wire busy;
  wire overrun_error;
  wire frame_error;

  always #4 clk = ~clk;

  uart_rx dut (
    .clk(clk),
    .rst(rst),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy),
    .overrun_error(overrun_error),
    .frame_error(frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int count);
    repeat (count) @(negedge clk);
  endtask

  // Drive an 8N1 frame, optionally replacing its stop bit with a low bit.
  task automatic send_frame(input logic [7:0] data, input bit bad_stop);
    rxd = 1'b0;
    wait_clks(BIT_CLOCKS);

    for (int i = 0; i < 8; i++) begin
      rxd = data[i];
      wait_clks(BIT_CLOCKS);
    end

    rxd = !bad_stop;
    wait_clks(BIT_CLOCKS);
    rxd = 1'b1;
  endtask

  initial begin
    wait_clks(5);
    rst = 1'b0;
    wait_clks(5);

    // Leave 3C pending throughout both following frames.
    send_frame(8'h3C, 1'b0);
    wait_clks(3 * BIT_CLOCKS);

    // The rejected stop bit produces frame_error without replacing 3C.
    send_frame(8'h5A, 1'b1);
    wait_clks(4 * BIT_CLOCKS);

    // This good frame replaces the stalled word and produces overrun_error.
    send_frame(8'hA5, 1'b0);
    wait_clks(3 * BIT_CLOCKS);

    $finish;
  end
endmodule
```

